START TRANSACTION;
UPDATE payment SET amount = amount - 5 WHERE payment_id = (SELECT payment_id FROM (SELECT payment_id FROM payment WHERE customer_id = 1 ORDER BY payment_date ASC LIMIT 1) AS t);
COMMIT;

START TRANSACTION;
UPDATE payment SET amount = amount - 3 WHERE payment_id = (SELECT payment_id FROM (SELECT payment_id FROM payment WHERE customer_id = 1 ORDER BY payment_date DESC LIMIT 1) AS t);
COMMIT;

WITH RECURSIVE nums(n) AS (
  SELECT 1
  UNION ALL
  SELECT n + 1 FROM nums WHERE n < 10
)
SELECT n FROM nums;

WITH cust_rev AS (
  SELECT customer_id, SUM(amount) AS total FROM payment GROUP BY customer_id
)
SELECT customer_id, total FROM cust_rev WHERE total > 150 ORDER BY total DESC;

WITH cust_rev AS (
  SELECT customer_id, SUM(amount) AS total FROM payment GROUP BY customer_id
)
SELECT customer_id, total, CASE WHEN total > 150 THEN 'Gold' WHEN total > 50 THEN 'Silver' ELSE 'Bronze' END AS tier FROM cust_rev;

WITH per_rating AS (
  SELECT rating, AVG(length) AS avg_len FROM film GROUP BY rating
),
overall AS (
  SELECT AVG(length) AS all_avg FROM film
)
SELECT pr.rating, pr.avg_len, o.all_avg, pr.avg_len - o.all_avg AS diff FROM per_rating pr CROSS JOIN overall o ORDER BY diff DESC;

WITH RECURSIVE dates(d) AS (
  SELECT DATE('2005-05-24')
  UNION ALL
  SELECT d + INTERVAL 1 DAY FROM dates WHERE d < DATE('2005-05-30')
)
SELECT d FROM dates;

WITH cust_rev AS (
  SELECT customer_id, SUM(amount) AS total FROM payment GROUP BY customer_id
)
SELECT customer_id, total, RANK() OVER (ORDER BY total DESC) AS spend_rank FROM cust_rev ORDER BY total DESC LIMIT 3;

WITH totals AS (
  SELECT customer_id, SUM(amount) AS total FROM payment GROUP BY customer_id
),
avg_total AS (
  SELECT AVG(total) AS a FROM totals
)
SELECT t.customer_id, t.total FROM totals t CROSS JOIN avg_total WHERE t.total > avg_total.a ORDER BY t.total DESC;

WITH ranked AS (
  SELECT title, rating, length, DENSE_RANK() OVER (PARTITION BY rating ORDER BY length DESC) AS rnk
  FROM film
)
SELECT title, rating, length, rnk FROM ranked WHERE rnk <= 3 ORDER BY rating, rnk;

WITH ranked AS (
  SELECT payment_id, customer_id, payment_date, amount, ROW_NUMBER() OVER (PARTITION BY customer_id ORDER BY payment_date DESC) AS rn FROM payment
)
SELECT payment_id, customer_id, payment_date, amount FROM ranked WHERE rn = 1;

WITH ranked AS (
  SELECT title, rating, length, ROW_NUMBER() OVER (PARTITION BY rating ORDER BY length DESC, title) AS rn FROM film
)
SELECT title, rating, length FROM ranked WHERE rn = 1;

WITH totals AS (
  SELECT customer_id, SUM(amount) AS total FROM payment GROUP BY customer_id
)
SELECT customer_id, total, RANK() OVER (ORDER BY total DESC) AS spend_rank FROM totals ORDER BY spend_rank;
